
@import url('https://fontsstorage.blob.core.windows.net/html/css/georama.css');
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');
:root{
 --red:#e31837;--red-dark:#b3122c;--red-soft:#fff0f2;--ink:#182230;--slate:#475467;
 --muted:#667085;--bg:#eef1f5;--card:#fff;--line:#dfe4ea;--nav:#17212f;
 --radius:16px;--shadow:0 4px 18px rgba(16,24,40,.055);--shadow-hover:0 12px 30px rgba(16,24,40,.09);
 --ease:cubic-bezier(.2,.8,.2,1)
}
*{box-sizing:border-box;margin:0;padding:0;font-family:'Georama-Regular', 'Georama_SemiExpanded-Regular', 'Plus Jakarta Sans',sans-serif}
body{background:var(--bg);color:var(--ink);min-height:100vh;overflow-x:hidden;font-family:'Georama-Regular', 'Georama_SemiExpanded-Regular', 'Plus Jakarta Sans',sans-serif}
button,input,select{font:inherit}button{cursor:pointer}
@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@keyframes slideIn{from{opacity:0;transform:translateX(-12px)}to{opacity:1;transform:translateX(0)}}
@keyframes spin{to{transform:rotate(360deg)}}
.view-screen{display:none;opacity:0}.view-screen.active{display:block;animation:fadeUp .4s var(--ease) forwards}

/* Login */
#login-view{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:28px;position:relative;overflow:hidden;
background:linear-gradient(115deg,rgba(9,18,31,.88),rgba(16,24,40,.55)),url('https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=2200&q=85') center/cover}
.login-shell{width:min(1080px,100%);display:grid;grid-template-columns:1.05fr .95fr;border-radius:26px;overflow:hidden;box-shadow:0 25px 70px rgba(0,0,0,.22)}
.login-visual{padding:54px;min-height:650px;color:white;display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(145deg,rgba(20,27,38,.8),rgba(227,24,55,.34))}
.login-brand{display:flex;align-items:center;gap:12px}.login-brand .mark{width:50px;height:50px;border-radius:14px;background:linear-gradient(135deg,#ff3552,var(--red-dark));display:grid;place-items:center;font-size:24px;font-weight:800}
.login-visual h1{font-size:45px;line-height:1.08;letter-spacing:-2px}.login-visual h1 span{color:#ff536b}.login-visual p{margin-top:17px;max-width:510px;line-height:1.7;color:rgba(255,255,255,.78)}
.visual-pills{display:flex;gap:9px;flex-wrap:wrap}.visual-pill{padding:8px 12px;border:1px solid rgba(255,255,255,.2);border-radius:99px;background:rgba(255,255,255,.08);font-size:11px}
.login-card{background:#fff;padding:45px 43px;position:relative}.login-card:before{content:"";position:absolute;top:0;left:0;right:0;height:5px;background:linear-gradient(90deg,var(--red-dark),var(--red),#17212f)}
.brand-header{display:flex;align-items:center;gap:12px;margin-bottom:30px}.brand-logo{width:46px;height:46px;border-radius:13px;background:linear-gradient(135deg,#ff3552,var(--red-dark));color:#fff;display:grid;place-items:center;font-size:22px;font-weight:800}
.brand-title b{font-size:19px}.brand-title span{color:var(--red)}.brand-title small{display:block;font-size:9px;color:var(--muted);letter-spacing:1.6px;font-weight:800}
.login-card h2{font-size:27px;margin-bottom:7px}.login-card>p{font-size:13px;color:var(--muted);line-height:1.6;margin-bottom:25px}
.form-group{margin-bottom:17px}.form-group label{display:block;font-size:12px;font-weight:700;color:var(--slate);margin-bottom:7px}
.form-control{width:100%;padding:13px 14px;border-radius:11px;border:1px solid var(--line);background:#fafbfc;outline:none;transition:.22s}.form-control:focus{border-color:var(--red);background:#fff;box-shadow:0 0 0 4px rgba(227,24,55,.08)}
.btn-primary{width:100%;border:0;padding:13px 17px;border-radius:11px;color:#fff;background:linear-gradient(135deg,var(--red),var(--red-dark));font-weight:800;font-size:13px;display:flex;align-items:center;justify-content:center;gap:8px;transition:.25s;box-shadow:0 8px 20px rgba(227,24,55,.18)}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 12px 25px rgba(227,24,55,.25)}
.login-hint{margin-top:16px;padding:11px 13px;border-radius:10px;background:var(--red-soft);color:#8e1930;font-size:10.5px;line-height:1.5}


/* Login alignment refinement */
#login-view{
  min-height:100vh;display:flex;align-items:center;justify-content:center;padding:34px;
  background:
    linear-gradient(120deg,rgba(8,16,28,.92),rgba(19,27,39,.68)),
    url('https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=2200&q=88') center/cover;
}
.login-shell{
  width:min(1120px,100%);display:grid;grid-template-columns:1fr 480px;
  border-radius:24px;overflow:hidden;background:#fff;
  box-shadow:0 28px 80px rgba(0,0,0,.28);min-height:650px;
}
.login-visual{
  min-width:0;padding:54px 58px;min-height:650px;position:relative;
  display:flex;flex-direction:column;justify-content:space-between;
  background:linear-gradient(145deg,rgba(10,18,31,.86),rgba(70,15,29,.68));
}
.login-visual:after{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 85% 15%,rgba(227,24,55,.26),transparent 34%);
  pointer-events:none;
}
.login-brand{position:relative;z-index:1;display:flex;align-items:center}
.login-brand img{
  display:block;width:275px;max-width:100%;height:auto;
  filter:brightness(0) invert(1);object-fit:contain;object-position:left center;
}
.login-visual-copy{position:relative;z-index:1;max-width:500px}
.login-visual-copy .eyebrow{font-size:11px;letter-spacing:2px;font-weight:800;color:#ff9eab;margin-bottom:14px}
.login-visual-copy h1{font-size:42px;line-height:1.08;letter-spacing:-1.8px;color:#fff;margin:0}
.login-visual-copy h1 span{color:#ff536b}
.login-visual-copy p{margin-top:16px;max-width:470px;line-height:1.7;color:rgba(255,255,255,.74);font-size:13px}
.login-card{width:auto;min-width:0;padding:48px 42px;background:#fff;display:flex;flex-direction:column;justify-content:center}
.login-card .brand-header{margin-bottom:30px}
.login-card .brand-header img{
  width:250px;max-width:100%;height:auto;display:block;
}
.login-card .brand-header .brand-title{display:none}
.login-card h2{font-size:28px;letter-spacing:-1px}
.login-card>p{font-size:13px;line-height:1.65;margin-bottom:25px}
.login-card .form-control{height:55px;font-size:15px}
.login-card .btn-primary{height:52px}
@media(max-width:900px){
  .login-shell{grid-template-columns:1fr;max-width:520px;min-height:auto}
  .login-visual{display:none}
}
@media(max-width:560px){
  #login-view{padding:14px}.login-card{padding:36px 24px}
}

/* Application */
#app-view{display:none;min-height:100vh;flex-direction:column;background:var(--bg)}#app-view.active{display:flex}
.navbar{height:70px;background:rgba(255,255,255,.96);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:sticky;top:0;z-index:200}
.app-brand{display:flex;align-items:center;gap:11px}.app-brand img{width:205px;height:auto;max-height:43px;object-fit:contain;object-position:left center}.app-brand-text b{font-size:16px}.app-brand-text b span{color:var(--red)}.app-brand-text small{display:block;color:var(--muted);font-size:8px;font-weight:800;letter-spacing:1.2px}
.nav-user-ctrl{display:flex;align-items:center;gap:10px}.user-badge{display:flex;align-items:center;gap:9px;padding:4px 9px;border-radius:12px}.user-badge:hover{background:#f4f5f7}
.avatar-sm{width:36px;height:36px;border-radius:11px;background:#1f2937;color:white;font-weight:800;display:grid;place-items:center;font-size:12px}
.btn-outline{background:#fff;border:1px solid var(--line);padding:8px 13px;border-radius:10px;font-weight:700;font-size:11px;color:var(--slate);transition:.2s}.btn-outline:hover{background:#f8fafc;border-color:#c9d0d9;transform:translateY(-1px)}
.menu-toggle{width:38px;height:38px;border:1px solid var(--line);background:#fff;border-radius:10px;font-size:18px;color:var(--slate);display:grid;place-items:center;margin-right:8px;transition:.2s}.menu-toggle:hover{color:var(--red);border-color:#f1b2bc}
.layout-body{display:flex;flex:1;min-width:0}
.sidebar{width:252px;flex:0 0 252px;background:#fff;border-right:1px solid var(--line);padding:18px 12px;display:flex;flex-direction:column;gap:5px;transition:width .28s var(--ease),flex-basis .28s var(--ease),padding .28s;position:sticky;top:70px;height:calc(100vh - 70px);overflow:hidden;z-index:100}
.sidebar-header{padding:7px 12px 13px;color:#98a2b3;font-size:9px;font-weight:800;letter-spacing:1.2px;white-space:nowrap}
.nav-item{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:10px;color:var(--slate);font-weight:700;font-size:12px;cursor:pointer;transition:.22s;position:relative;white-space:nowrap}
.nav-item > span:first-child{width:27px;height:27px;flex:0 0 27px;border-radius:8px;background:#f2f4f7;display:grid;place-items:center;font-size:14px}.nav-item:hover{background:#fff4f5;color:var(--red);transform:translateX(2px)}
.nav-item.active{background:var(--red-soft);color:var(--red);box-shadow:inset 3px 0 var(--red)}.nav-item.active > span:first-child{background:#fff;color:var(--red)}
.sidebar.collapsed{width:72px;flex-basis:72px;padding:18px 9px}.sidebar.collapsed .sidebar-header,.sidebar.collapsed .nav-label{display:none}.sidebar.collapsed .nav-item{justify-content:center;padding:11px}.sidebar.collapsed .nav-item:hover{transform:none}
.content-area{flex:1;min-width:0;padding:27px 30px 40px;max-width:1480px;margin:0 auto;width:100%}
.header-actions{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:20px;gap:18px}.header-actions h1{font-size:25px!important;letter-spacing:-.8px;margin-top:3px}
.profile-banner{background:#fff;border:1px solid var(--line);border-radius:17px;overflow:hidden;margin-bottom:21px;box-shadow:var(--shadow)}.profile-banner-top{height:6px;background:linear-gradient(90deg,var(--red-dark),var(--red) 55%,#17212f)}
.profile-inner{padding:24px;display:flex;gap:20px;align-items:center}.profile-avatar{width:78px;height:78px;background:linear-gradient(145deg,#17212f,#475467);border-radius:19px;color:#fff;display:grid;place-items:center;font-size:24px;font-weight:800}
.badge-status{background:#ecfdf3;color:#027a48;font-size:10px;font-weight:800;padding:5px 9px;border-radius:99px;display:inline-block}.meta-grid{display:flex;flex-wrap:wrap;gap:9px 19px;margin-top:11px;font-size:11px;color:var(--muted)}.meta-item strong{color:var(--ink)}
.sub-tabs{display:flex;gap:3px;border-bottom:1px solid var(--line);margin-bottom:20px;overflow-x:auto}.sub-tab{padding:11px 14px;background:none;border:0;font-size:12px;font-weight:700;color:var(--muted);border-bottom:2px solid transparent;transition:.2s;white-space:nowrap}.sub-tab:hover,.sub-tab.active{color:var(--red)}.sub-tab.active{border-bottom-color:var(--red)}
.grid-two-col{display:grid;grid-template-columns:minmax(0,2fr) minmax(270px,1fr);gap:18px}.card{background:#fff;border:1px solid var(--line);border-radius:15px;padding:20px;box-shadow:var(--shadow);margin-bottom:18px;transition:.25s}.card:hover{box-shadow:var(--shadow-hover);transform:translateY(-1px)}
.card-title{font-size:14px;font-weight:800;margin-bottom:15px;display:flex;justify-content:space-between;align-items:center}.stats-row{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:9px;margin-top:15px}.stat-box{background:#f7f8fa;border:1px solid #e8ebef;border-radius:11px;padding:12px}.stat-box small{display:block;color:var(--muted);font-size:9px;margin-bottom:4px}.stat-box b{font-size:17px}
.skill-row{margin-bottom:14px}.skill-header{display:flex;justify-content:space-between;font-size:11px;font-weight:700;margin-bottom:6px}.skill-bar{height:7px;background:#e9edf1;border-radius:99px;overflow:hidden}.skill-fill{height:100%;background:linear-gradient(90deg,var(--red-dark),var(--red));border-radius:99px;transition:width .8s ease}
.box-matrix{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:10px}.box-matrix-cell{background:#f5f6f8;border-radius:8px;padding:15px 7px;text-align:center;font-size:10px;font-weight:700;color:var(--slate);display:flex;flex-direction:column;justify-content:center}.box-matrix-cell.highlight{background:var(--red-soft);color:var(--red);border:1px solid #f0adb7;box-shadow:0 6px 16px rgba(227,24,55,.08)}
.data-table{width:100%;border-collapse:separate;border-spacing:0;font-size:11px}.data-table th{padding:11px;text-align:left;background:#f7f8fa;color:var(--slate);border-bottom:1px solid var(--line);font-size:9px;text-transform:uppercase;letter-spacing:.3px}.data-table td{padding:12px 11px;border-bottom:1px solid var(--line);background:#fff}.data-table tbody tr:hover td{background:#fff8f9}
.toast-box{position:fixed;bottom:22px;right:22px;background:#17212f;color:#fff;padding:12px 16px;border-radius:10px;box-shadow:0 12px 30px rgba(0,0,0,.16);display:none;font-size:11px;font-weight:700;z-index:9999;border-left:3px solid var(--red)}
@media(max-width:900px){.sidebar{width:72px;flex-basis:72px;padding:18px 9px}.sidebar-header,.nav-label{display:none}.nav-item{justify-content:center}.grid-two-col{grid-template-columns:1fr}.content-area{padding:22px}}
@media(max-width:700px){.login-shell{grid-template-columns:1fr}.login-visual{display:none}.login-card{padding:34px 24px}.navbar{padding:0 12px}.app-brand-text{display:none}.content-area{padding:16px}.header-actions{flex-direction:column;align-items:flex-start}.profile-inner{padding:18px;align-items:flex-start}.profile-avatar{width:64px;height:64px}.meta-grid{display:grid;grid-template-columns:1fr}.data-table{min-width:650px}.card{overflow:auto}}

/* Dashboard */
.dashboard-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}
.kpi-card{background:#fff;border:1px solid var(--line);border-radius:15px;padding:18px;box-shadow:var(--shadow);position:relative;overflow:hidden;transition:.25s}
.kpi-card:hover{transform:translateY(-2px);box-shadow:var(--shadow-hover)}
.kpi-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.kpi-icon{width:36px;height:36px;border-radius:10px;background:var(--red-soft);color:var(--red);display:grid;place-items:center;font-weight:800}
.kpi-label{font-size:10px;color:var(--muted);font-weight:700}
.kpi-value{font-size:25px;font-weight:800;letter-spacing:-1px}.kpi-change{font-size:10px;color:#027a48;font-weight:800;margin-top:4px}
.kpi-accent{position:absolute;left:0;bottom:0;height:3px;width:100%;background:linear-gradient(90deg,var(--red-dark),var(--red))}
.dashboard-charts{display:grid;grid-template-columns:1.45fr 1fr;gap:18px;margin-bottom:18px}
.chart-card{background:#fff;border:1px solid var(--line);border-radius:15px;padding:19px;box-shadow:var(--shadow);min-height:315px}
.chart-card.wide{min-height:350px}.chart-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:13px}
.chart-title{font-size:14px;font-weight:800}.chart-subtitle{font-size:10px;color:var(--muted);margin-top:4px}
.chart-wrap{height:235px;position:relative}.chart-card.wide .chart-wrap{height:270px}
.dashboard-bottom{display:grid;grid-template-columns:1.2fr .8fr;gap:18px}
.pipeline-list{display:flex;flex-direction:column;gap:13px}
.pipeline-item{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center}
.pipeline-name{font-size:11px;font-weight:700}.pipeline-meta{font-size:9px;color:var(--muted);margin-top:3px}
.pipeline-bar{height:7px;background:#edf0f3;border-radius:99px;overflow:hidden;margin-top:7px}.pipeline-fill{height:100%;background:linear-gradient(90deg,var(--red-dark),var(--red));border-radius:99px}
.pipeline-pct{font-size:11px;font-weight:800;color:var(--slate)}
.quick-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.quick-action{border:1px solid var(--line);background:#fafbfc;border-radius:11px;padding:13px;text-align:left;transition:.2s}.quick-action:hover{background:var(--red-soft);border-color:#f0b0ba;transform:translateY(-1px)}
.quick-action b{display:block;font-size:11px}.quick-action span{font-size:9px;color:var(--muted);display:block;margin-top:4px}
@media(max-width:1100px){.dashboard-grid{grid-template-columns:repeat(2,1fr)}.dashboard-charts,.dashboard-bottom{grid-template-columns:1fr}}
@media(max-width:600px){.dashboard-grid{grid-template-columns:1fr}.chart-wrap,.chart-card.wide .chart-wrap{height:220px}}


/* FINAL UI REFINEMENT */
.login-shell{grid-template-columns:minmax(0,1fr) 480px;min-height:650px}
.login-visual{position:relative;overflow:hidden;padding:52px 58px}
.login-visual-brand{position:relative;z-index:2}
.login-visual-brand img{width:285px;height:auto;display:block;filter:brightness(0) invert(1)}
.login-visual-copy{position:relative;z-index:2;margin-top:auto;margin-bottom:auto;max-width:510px}
.login-visual-copy .eyebrow{font-size:10px;letter-spacing:2px;font-weight:800;color:#ff9eab;margin-bottom:13px}
.login-visual-copy h1{font-size:43px!important;line-height:1.08!important;letter-spacing:-1.7px;color:#fff!important;margin:0!important}
.login-visual-copy h1 span{color:#ff526a!important}
.login-visual-copy p{font-size:13px!important;line-height:1.7!important;color:rgba(255,255,255,.76)!important;margin-top:17px!important;max-width:480px}
.login-visual-copy .visual-pills{margin-top:24px}
.login-visual-footer{position:relative;z-index:2;display:flex;gap:18px;flex-wrap:wrap;color:rgba(255,255,255,.48);font-size:9px;letter-spacing:.4px}
.login-card{padding:44px 42px!important}
.login-card-logo{margin-bottom:29px}
.login-card-logo img{width:235px;height:auto;display:block}
.login-kicker{font-size:9px;letter-spacing:1.5px;color:var(--red);font-weight:800;margin-bottom:7px}
.login-card-heading h2{font-size:29px!important;line-height:1.15;margin-bottom:8px!important}
.login-card-heading p{font-size:12.5px!important;line-height:1.65!important;margin-bottom:25px!important}
.login-card .form-group{margin-bottom:16px}
.login-card .form-control{height:53px}
.login-card .btn-primary{height:52px}
.login-hint{display:flex;align-items:flex-start;gap:8px;margin-top:15px!important}
.hint-dot{width:6px;height:6px;flex:0 0 6px;border-radius:50%;background:var(--red);margin-top:5px}
.login-card-footer{margin-top:19px;color:#98a2b3;font-size:8.5px;text-align:center}

/* Sidebar edge toggle */
.sidebar{position:relative}
.sidebar-toggle-wrap{margin-top:auto;padding:14px 4px 2px;border-top:1px solid var(--line);display:flex;justify-content:flex-end}
.sidebar-toggle{width:38px;height:30px;border:1px solid var(--line);background:#fff;border-radius:8px;color:var(--slate);font-size:22px;line-height:1;display:grid;place-items:center;transition:.2s}
.sidebar-toggle:hover{color:var(--red);border-color:#f1b2bc;background:var(--red-soft)}
.sidebar.collapsed .sidebar-toggle-wrap{justify-content:center}
.sidebar.collapsed .sidebar-toggle{width:38px}
.sidebar.collapsed #sidebarToggleIcon{transform:rotate(180deg);display:block}

/* Keep application background clean and consistent */
#app-view{background:#eef1f5}
.content-area{background:transparent}


@media(max-width:980px){
  .login-shell{grid-template-columns:1fr 440px}
  .login-visual{padding:46px}
  .login-visual-brand img{width:245px}
}
@media(max-width:820px){
  .login-shell{grid-template-columns:1fr;max-width:520px;min-height:auto}
  .login-visual{display:none}
}
@media(max-width:700px){
  .sidebar{width:72px;flex-basis:72px;padding:18px 9px}
  .sidebar-header,.nav-label{display:none}
  .nav-item{justify-content:center}
  .sidebar-toggle-wrap{justify-content:center}
  .content-area{padding:18px 16px 32px}
}


/* === FINAL DASHBOARD ALIGNMENT FIX === */
.navbar{height:70px;position:sticky;top:0;z-index:300}
.layout-body{align-items:stretch;min-height:calc(100vh - 70px)}
.sidebar{
  position:sticky;top:70px;height:calc(100vh - 70px);
  align-self:flex-start;margin-top:0;
}
.content-area{
  padding:30px 30px 44px;
  min-width:0;
  overflow:hidden;
}
.sub-view{width:100%;max-width:100%}

/* Dashboard/header stays inside the content column; no artificial top gap. */
#page-dashboard .header-actions{margin-top:0}
#page-dashboard{width:100%}

/* Prevent charts/cards from pushing outside the dashboard column. */
.dashboard-grid,.dashboard-charts{width:100%;max-width:100%}
.chart-card,.kpi-card{min-width:0;max-width:100%}
.chart-wrap{width:100%;min-width:0}
.chart-wrap canvas{max-width:100%!important}

/* Sidebar toggle stays at the bottom edge of the sidebar. */
.sidebar-toggle-wrap{margin-top:auto}
@media(max-width:900px){
  .content-area{padding:22px 20px 36px}
}
@media(max-width:700px){
  .content-area{padding:18px 16px 32px}
}

.nav-item .nav-label{background:transparent!important;width:auto;height:auto;flex:none;border-radius:0;display:inline;color:inherit;font-size:inherit}

/* Global Georama typography */
html, body, body *,
button, input, select, textarea, option {
  font-family: 'Georama-Regular', sans-serif !important;
}


/* ==========================================================
   MAHINDRA RISE — GLASSMORPHISM DESIGN
   Inspired by the supplied Lumina glass dashboard reference.
   Existing content/functionality is intentionally preserved.
   ========================================================== */

:root{
  --glass-red:#e31837;
  --glass-red-dark:#bd102d;
  --glass-white:rgba(255,255,255,.78);
  --glass-surface:rgba(255,255,255,.15);
  --glass-surface-strong:rgba(255,255,255,.22);
  --glass-border:rgba(255,255,255,.42);
  --glass-text:#172235;
  --glass-muted:#5e6b80;
  --glass-shadow:0 18px 50px rgba(18,30,60,.12);
  --glass-blur:22px;
}

/* ---------- Global background ---------- */
body{
  font-family:'Georama-Regular',sans-serif!important;
  background:#dfe6f3!important;
}
#app-view{
  position:relative;
  isolation:isolate;
  overflow:hidden;
  background:
    radial-gradient(circle at 9% 8%,rgba(129,87,255,.34),transparent 29%),
    radial-gradient(circle at 87% 10%,rgba(0,196,255,.32),transparent 30%),
    radial-gradient(circle at 92% 80%,rgba(255,94,168,.26),transparent 31%),
    radial-gradient(circle at 38% 88%,rgba(81,104,255,.22),transparent 34%),
    linear-gradient(135deg,#edf1fa 0%,#e5ebf6 42%,#dce8f4 100%)!important;
}
#app-view:before,
#app-view:after{
  content:"";
  position:absolute;
  border-radius:50%;
  pointer-events:none;
  filter:blur(8px);
  z-index:-1;
}
#app-view:before{
  width:430px;height:430px;left:-190px;top:90px;
  background:rgba(132,76,255,.18);
}
#app-view:after{
  width:500px;height:500px;right:-190px;bottom:-180px;
  background:rgba(237,49,130,.16);
}
.layout-body,
.content-area,
.sub-view{position:relative;z-index:1}

/* ---------- Glass utility ---------- */
.navbar,
.sidebar,
.card,
.kpi-card,
.chart-card,
.profile-banner,
.report-toolbar,
.report-row{
  background:rgba(255,255,255,.43)!important;
  border:1px solid rgba(255,255,255,.62)!important;
  backdrop-filter:blur(var(--glass-blur)) saturate(135%)!important;
  -webkit-backdrop-filter:blur(var(--glass-blur)) saturate(135%)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.78),
    0 18px 45px rgba(31,47,79,.11)!important;
}

/* ---------- Header ---------- */
.navbar{
  background:rgba(255,255,255,.57)!important;
  border-bottom:1px solid rgba(255,255,255,.65)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.9),
    0 10px 32px rgba(30,45,75,.09)!important;
}
.app-brand img{filter:none!important}
.app-brand-text b{color:var(--glass-text)!important}
.app-brand-text small{color:#66758d!important}
.user-badge{
  background:rgba(255,255,255,.18)!important;
  border:1px solid rgba(255,255,255,.28);
  backdrop-filter:blur(12px);
}
.avatar-sm{
  background:linear-gradient(145deg,#25344c,#536580)!important;
  box-shadow:0 8px 18px rgba(28,43,70,.18)!important;
}

/* ---------- Sidebar ---------- */
.sidebar{
  background:rgba(255,255,255,.40)!important;
  border-right:1px solid rgba(255,255,255,.55)!important;
  box-shadow:
    inset -1px 0 0 rgba(255,255,255,.5),
    10px 0 35px rgba(31,47,79,.08)!important;
}
.sidebar-header{
  color:#73819a!important;
}
.nav-item{
  color:#536179!important;
  background:transparent!important;
  border:1px solid transparent!important;
  box-shadow:none!important;
  transition:.25s ease!important;
}
.nav-item span:first-child{
  background:rgba(255,255,255,.34)!important;
  border:1px solid rgba(255,255,255,.55)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.72),
    0 7px 18px rgba(45,62,92,.08)!important;
}
.nav-item:hover{
  background:rgba(255,255,255,.24)!important;
  border-color:rgba(255,255,255,.4)!important;
  color:var(--glass-red)!important;
  transform:translateX(3px)!important;
  box-shadow:0 8px 20px rgba(35,51,82,.07)!important;
}
.nav-item.active{
  background:linear-gradient(100deg,rgba(255,237,241,.76),rgba(255,255,255,.34))!important;
  border:1px solid rgba(255,255,255,.64)!important;
  color:var(--glass-red)!important;
  box-shadow:
    inset 4px 0 0 var(--glass-red),
    inset 0 1px 0 rgba(255,255,255,.85),
    0 12px 28px rgba(35,51,82,.10)!important;
}
.nav-item.active span:first-child{
  background:rgba(255,255,255,.66)!important;
  color:var(--glass-red)!important;
}
.sidebar-toggle-wrap{
  border-top:1px solid rgba(255,255,255,.38)!important;
}
.sidebar-toggle{
  background:rgba(255,255,255,.34)!important;
  border:1px solid rgba(255,255,255,.55)!important;
  box-shadow:0 8px 18px rgba(35,51,82,.10)!important;
}
.sidebar-toggle:hover{
  background:rgba(255,255,255,.58)!important;
}

/* ---------- Page headings ---------- */
.header-actions h1,
.header-actions h2,
.card-title,
.chart-title,
.kpi-value,
.kpi-label,
.report-row b{
  color:var(--glass-text)!important;
}
.header-actions .eyebrow,
.header-actions span[style*="color:var(--red)"]{
  text-shadow:0 1px 1px rgba(255,255,255,.55);
}

/* ---------- KPI cards ---------- */
.kpi-card{
  position:relative;
  overflow:hidden;
  transition:transform .25s ease,box-shadow .25s ease!important;
}
.kpi-card:before{
  content:"";
  position:absolute;
  width:130px;height:130px;
  right:-65px;top:-65px;
  border-radius:50%;
  background:rgba(255,255,255,.25);
  filter:blur(2px);
}
.kpi-card:hover{
  transform:translateY(-4px)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.9),
    0 25px 55px rgba(31,47,79,.16)!important;
}
.kpi-icon{
  background:rgba(255,255,255,.36)!important;
  border:1px solid rgba(255,255,255,.55)!important;
  box-shadow:0 8px 18px rgba(35,51,82,.08)!important;
}
.kpi-accent{
  background:linear-gradient(90deg,var(--glass-red),#ef4963)!important;
}

/* ---------- Main cards ---------- */
.card,.chart-card{
  transition:transform .25s ease,box-shadow .25s ease!important;
}
.card:hover,.chart-card:hover{
  transform:translateY(-3px)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.9),
    0 25px 55px rgba(31,47,79,.14)!important;
}

/* ---------- Charts ---------- */
.chart-card{
  background:rgba(255,255,255,.38)!important;
}
.chart-wrap{
  background:rgba(255,255,255,.08)!important;
  border-radius:14px;
}

/* ---------- Profile ---------- */
.profile-banner{
  background:linear-gradient(110deg,rgba(255,255,255,.52),rgba(255,255,255,.27))!important;
}
.profile-banner-top{
  background:linear-gradient(90deg,var(--glass-red-dark),var(--glass-red),#26344a)!important;
}
.profile-avatar{
  background:linear-gradient(145deg,#25344c,#60708a)!important;
  box-shadow:0 13px 25px rgba(28,43,70,.18)!important;
}

/* ---------- Inputs / filters ---------- */
.form-control,
.filter-chip,
.btn-outline{
  background:rgba(255,255,255,.38)!important;
  border:1px solid rgba(255,255,255,.58)!important;
  backdrop-filter:blur(12px)!important;
  -webkit-backdrop-filter:blur(12px)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.75),
    0 7px 18px rgba(35,51,82,.07)!important;
}
.form-control:focus{
  background:rgba(255,255,255,.58)!important;
  border-color:rgba(227,24,55,.35)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.8),
    0 0 0 3px rgba(227,24,55,.10),
    0 9px 22px rgba(35,51,82,.08)!important;
}
.btn-outline:hover{
  background:rgba(255,255,255,.62)!important;
}
.btn-primary{
  background:linear-gradient(135deg,#ef1b3b,#c70e2b)!important;
  box-shadow:
    0 13px 28px rgba(190,20,48,.24),
    inset 0 1px 0 rgba(255,255,255,.25)!important;
}

/* ---------- Report filters ---------- */
.report-toolbar{
  background:rgba(255,255,255,.23)!important;
  box-shadow:none!important;
  border:0!important;
}
.filter-chip{
  color:var(--glass-muted)!important;
}
.report-updated{
  color:#66758d!important;
}

/* ---------- Reports ---------- */
.report-row{
  background:rgba(255,255,255,.34)!important;
}
.report-row:hover{
  background:rgba(255,255,255,.55)!important;
  transform:translateY(-3px)!important;
}
.report-icon{
  background:rgba(255,255,255,.42)!important;
  border:1px solid rgba(255,255,255,.55)!important;
  box-shadow:0 8px 18px rgba(35,51,82,.08)!important;
}

/* ---------- Stats / matrix ---------- */
.stat-box,
.box-matrix-cell{
  background:rgba(255,255,255,.25)!important;
  border:1px solid rgba(255,255,255,.42)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.6),
    0 6px 15px rgba(35,51,82,.05)!important;
}
.box-matrix-cell.highlight{
  background:rgba(255,235,239,.54)!important;
  border-color:rgba(227,24,55,.24)!important;
}

/* ---------- Table ---------- */
.data-table th{
  background:rgba(255,255,255,.25)!important;
}
.data-table td{
  background:rgba(255,255,255,.12)!important;
}
.data-table tbody tr:hover td{
  background:rgba(255,255,255,.36)!important;
}

/* ---------- Login glass treatment ---------- */
#login-view{
  min-height:100vh!important;
  padding:34px!important;
  background:
    radial-gradient(circle at 10% 10%,rgba(136,75,255,.45),transparent 30%),
    radial-gradient(circle at 90% 12%,rgba(0,192,255,.40),transparent 31%),
    radial-gradient(circle at 88% 88%,rgba(255,75,156,.34),transparent 30%),
    linear-gradient(135deg,#17223d 0%,#302553 48%,#173f5d 100%)!important;
}
#login-view:before{
  content:"";
  position:absolute;
  width:430px;height:430px;
  left:-170px;bottom:-170px;
  border-radius:50%;
  background:rgba(255,255,255,.08);
  filter:blur(8px);
}
.login-shell{
  background:rgba(255,255,255,.13)!important;
  border:1px solid rgba(255,255,255,.34)!important;
  backdrop-filter:blur(26px)!important;
  -webkit-backdrop-filter:blur(26px)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.35),
    0 30px 80px rgba(5,12,28,.30)!important;
}
.login-visual{
  background:linear-gradient(145deg,rgba(33,22,67,.48),rgba(13,53,77,.34))!important;
  border-right:1px solid rgba(255,255,255,.20);
}
.login-card{
  background:rgba(255,255,255,.78)!important;
  backdrop-filter:blur(24px)!important;
  -webkit-backdrop-filter:blur(24px)!important;
  border-left:1px solid rgba(255,255,255,.55);
  box-shadow:
    inset 1px 0 0 rgba(255,255,255,.45),
    0 20px 50px rgba(7,16,35,.15)!important;
}
.login-card .form-control{
  background:rgba(255,255,255,.45)!important;
}
.login-hint{
  background:rgba(255,235,239,.52)!important;
  border:1px solid rgba(255,255,255,.52)!important;
}

/* ---------- Glass page badges ---------- */
.badge-status{
  background:rgba(236,253,243,.62)!important;
  border:1px solid rgba(255,255,255,.58);
  backdrop-filter:blur(10px);
}

/* ---------- Responsive ---------- */
@media(max-width:900px){
  .sidebar{
    background:rgba(255,255,255,.55)!important;
  }
}
@media(max-width:700px){
  #login-view{padding:14px!important}
  .login-card{border-left:0}
  .navbar,.sidebar,.card,.kpi-card,.chart-card,.report-row{
    backdrop-filter:blur(18px)!important;
    -webkit-backdrop-filter:blur(18px)!important;
  }
}


/* === Fixed sidebar / scrollable content === */
html, body {
  width:100%;
  height:100%;
  min-height:100%;
  overflow:hidden;
}
#app-view {
  height:100vh !important;
  min-height:100vh !important;
  overflow:hidden !important;
  display:flex;
  flex-direction:column;
}
.navbar {
  flex:0 0 70px;
  height:70px !important;
}
.layout-body {
  flex:1 1 auto;
  min-height:0 !important;
  height:calc(100vh - 70px);
  overflow:hidden !important;
  align-items:stretch;
}
.sidebar {
  flex:0 0 252px;
  width:252px;
  height:100% !important;
  min-height:0 !important;
  position:relative !important;
  top:auto !important;
  align-self:stretch !important;
  overflow:hidden !important;
}
.sidebar.collapsed {
  flex-basis:72px;
  width:72px;
}
.content-area {
  flex:1 1 auto;
  width:auto;
  min-width:0;
  min-height:0 !important;
  height:100%;
  overflow-y:auto !important;
  overflow-x:hidden !important;
  overscroll-behavior:contain;
  scrollbar-width:thin;
  scrollbar-color:rgba(102,117,141,.35) transparent;
}
.content-area::-webkit-scrollbar{width:8px}
.content-area::-webkit-scrollbar-track{background:transparent}
.content-area::-webkit-scrollbar-thumb{
  background:rgba(102,117,141,.30);
  border-radius:99px;
  border:2px solid transparent;
  background-clip:padding-box;
}
.content-area::-webkit-scrollbar-thumb:hover{
  background:rgba(102,117,141,.48);
  background-clip:padding-box;
}

/* Keep sidebar controls visible at the bottom while content scrolls */
.sidebar-toggle-wrap {
  flex:0 0 auto;
}

/* Mobile keeps the same principle: content scrolls, sidebar stays fixed */
@media(max-width:900px){
  .sidebar {
    flex:0 0 72px;
    width:72px;
    height:100% !important;
  }
  .content-area {
    height:100%;
    overflow-y:auto !important;
  }
}


html,body,body *,button,input,select,textarea,option{
  font-family:'Georama-Regular',sans-serif!important;
}


/* ==========================================================
   MAHINDRA RISE LOGIN — IMAGE HERO
   ========================================================== */
#login-view{
  position:relative!important;
  min-height:100vh!important;
  padding:28px!important;
  background:
    linear-gradient(90deg,rgba(5,13,28,.18),rgba(5,13,28,.02) 62%,rgba(7,15,31,.20)),
    url("data:image/jpeg;base64,") left center / cover no-repeat,
    linear-gradient(135deg,#18253d,#315878)!important;
}
#login-view:after{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:
    radial-gradient(circle at 8% 12%,rgba(161,95,255,.18),transparent 28%),
    radial-gradient(circle at 76% 88%,rgba(255,70,150,.16),transparent 25%);
  mix-blend-mode:screen;
}
#login-view .login-shell{
  position:relative!important;
  z-index:2!important;
  background:transparent!important;
  border:0!important;
  box-shadow:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  overflow:visible!important;
}
#login-view .login-visual{
  position:relative!important;
  min-height:calc(100vh - 56px)!important;
  background:transparent!important;
  border:0!important;
  box-shadow:none!important;
  overflow:hidden!important;
}
/* The generated hero already contains the Mahindra branding and hero copy. */
#login-view .login-visual-brand,
#login-view .login-visual-copy,
#login-view .login-visual-footer{
  display:none!important;
}
#login-view .login-card{
  align-self:center!important;
  margin:0!important;
  background:rgba(255,255,255,.72)!important;
  border:1px solid rgba(255,255,255,.58)!important;
  border-radius:24px!important;
  backdrop-filter:blur(26px) saturate(135%)!important;
  -webkit-backdrop-filter:blur(26px) saturate(135%)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.85),
    0 28px 70px rgba(4,12,28,.25)!important;
}
#login-view .login-card-logo img{
  width:230px!important;
}
#login-view .login-card-heading h2{
  color:#182438!important;
}
#login-view .login-card-heading p{
  color:#5d6b80!important;
}
#login-view .login-card .form-control{
  background:rgba(255,255,255,.48)!important;
  border:1px solid rgba(255,255,255,.66)!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.82),0 8px 20px rgba(30,48,77,.07)!important;
}
#login-view .login-card .form-control:focus{
  background:rgba(255,255,255,.68)!important;
  border-color:rgba(227,24,55,.30)!important;
}
#login-view .login-card .btn-primary{
  background:linear-gradient(135deg,#ed1738,#c90d2d)!important;
  box-shadow:0 14px 28px rgba(201,13,45,.26),inset 0 1px 0 rgba(255,255,255,.24)!important;
}
#login-view .login-hint{
  background:rgba(255,237,241,.52)!important;
  border:1px solid rgba(255,255,255,.55)!important;
}
@media(max-width:820px){
  #login-view{
    padding:14px!important;
    background-position:left center!important;
  }
  #login-view .login-card{
    margin:auto!important;
  }
}


/* ==========================================================
   LOGIN SCREEN — VIEWPORT SAFE / NO OVERFLOW
   ========================================================== */
html, body {
  width:100%;
  min-height:100%;
  margin:0;
  overflow-x:hidden;
}

#login-view{
  position:relative!important;
  width:100vw!important;
  min-width:0!important;
  height:100vh!important;
  min-height:560px!important;
  max-height:100vh!important;
  box-sizing:border-box!important;
  padding:clamp(18px,3vw,34px)!important;
  overflow:hidden!important;

  /* Keep the complete hero image inside the viewport. */
  background:
    linear-gradient(90deg,rgba(6,14,29,.20),rgba(6,14,29,.04) 58%,rgba(6,14,29,.18)),
    url("data:image/jpeg;base64,") center center / cover no-repeat!important;
}

#login-view .login-shell{
  width:min(1180px,100%)!important;
  height:min(720px,calc(100vh - 36px))!important;
  min-height:0!important;
  margin:auto!important;
  display:grid!important;
  grid-template-columns:minmax(0,1fr) minmax(380px,450px)!important;
  gap:clamp(14px,2vw,26px)!important;
  box-sizing:border-box!important;
  overflow:hidden!important;
  border-radius:24px!important;
  position:relative!important;
  z-index:2!important;
}

#login-view .login-visual{
  min-width:0!important;
  min-height:0!important;
  height:100%!important;
  padding:clamp(30px,4vw,56px)!important;
  box-sizing:border-box!important;
  overflow:hidden!important;
  display:flex!important;
  flex-direction:column!important;
  justify-content:flex-end!important;
  background:linear-gradient(90deg,rgba(12,18,37,.32),rgba(12,18,37,.06))!important;
  border-radius:22px!important;
}

/* Hide duplicate copy because the hero image already contains the artwork/text. */
#login-view .login-visual-brand,
#login-view .login-visual-copy,
#login-view .login-visual-footer{
  display:none!important;
}

#login-view .login-card{
  width:auto!important;
  min-width:0!important;
  height:100%!important;
  max-height:100%!important;
  box-sizing:border-box!important;
  overflow:auto!important;
  align-self:stretch!important;
  margin:0!important;
  padding:clamp(28px,3.2vw,44px) clamp(26px,3vw,42px)!important;
  border-radius:22px!important;
  background:rgba(255,255,255,.76)!important;
  border:1px solid rgba(255,255,255,.65)!important;
  backdrop-filter:blur(26px) saturate(135%)!important;
  -webkit-backdrop-filter:blur(26px) saturate(135%)!important;
}

#login-view .login-card-logo{
  margin-bottom:clamp(18px,2.5vh,28px)!important;
}
#login-view .login-card-logo img{
  width:min(220px,72%)!important;
  max-width:100%!important;
  height:auto!important;
}

#login-view .login-card-heading h2{
  font-size:clamp(24px,2.1vw,30px)!important;
  line-height:1.15!important;
}
#login-view .login-card-heading p{
  font-size:12px!important;
  line-height:1.55!important;
  margin-bottom:20px!important;
}
#login-view .login-card .form-group{
  margin-bottom:13px!important;
}
#login-view .login-card .form-control{
  width:100%!important;
  height:50px!important;
  box-sizing:border-box!important;
}
#login-view .login-card .btn-primary{
  width:100%!important;
  height:50px!important;
  margin-top:2px!important;
}
#login-view .login-hint{
  margin-top:12px!important;
}
#login-view .login-card-footer{
  margin-top:14px!important;
}

/* Short laptop screens: compact the card so nothing falls below the viewport. */
@media (max-height:760px) and (min-width:821px){
  #login-view{
    padding:16px!important;
  }
  #login-view .login-shell{
    height:calc(100vh - 32px)!important;
  }
  #login-view .login-card{
    padding:22px 30px!important;
  }
  #login-view .login-card-logo{
    margin-bottom:14px!important;
  }
  #login-view .login-card-heading p{
    margin-bottom:14px!important;
  }
  #login-view .login-card .form-group{
    margin-bottom:10px!important;
  }
  #login-view .login-card .form-control,
  #login-view .login-card .btn-primary{
    height:46px!important;
  }
}

/* Tablet / mobile: use the complete background and a single card. */
@media(max-width:820px){
  #login-view{
    height:100svh!important;
    min-height:600px!important;
    padding:14px!important;
    background-position:center center!important;
  }
  #login-view .login-shell{
    width:min(520px,100%)!important;
    height:min(720px,calc(100svh - 28px))!important;
    display:block!important;
  }
  #login-view .login-visual{
    display:none!important;
  }
  #login-view .login-card{
    width:100%!important;
    height:100%!important;
    border-radius:22px!important;
  }
}

/* Very small mobile screens: allow only the card to scroll. */
